}

.spell-quest-wrapper .trophy-container {
  margin-bottom: 1.5rem;
}

.spell-quest-wrapper .trophy-icon {
  width: 80px;
  height: 80px;
  color: #f59e0b;
  animation: trophyBounce 1s ease infinite;
}

@keyframes trophyBounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}

.spell-quest-wrapper .complete-title {
  font-size: 2.5rem;
  font-weight: 800;
  color: #1e40af;
  margin: 0 0 0.5rem 0;
}

.spell-quest-wrapper .complete-subtitle {
  font-size: 1.125rem;
  color: #6b7280;
  margin: 0 0 2rem 0;
}

.spell-quest-wrapper .final-stats {
