  font-weight: 800;
  color: #1e40af;
}

.spell-quest-wrapper .complete-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.spell-quest-wrapper .play-again-btn {
  background: linear-gradient(135deg, #3b82f6, #1d4ed8);
  color: white;
  font-weight: 700;
  padding: 0.75rem 2rem;
}

.spell-quest-wrapper .play-again-btn:hover {
  background: linear-gradient(135deg, #2563eb, #1e40af);
}

/* Footer */
.spell-quest-wrapper .game-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 1.5rem;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(10px);
  padding: 1rem 1.5rem;
  border-radius: 1rem;
  flex-wrap: wrap;
}

.spell-quest-wrapper .footer-buttons {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.spell-quest-wrapper .footer-button {
  background: white;
  border: 2px solid #e2e8f0;
  gap: 0.5rem;
}

.spell-quest-wrapper .footer-button:hover {
  background: #eff6ff;
  border-color: #3b82f6;
}

.spell-quest-wrapper .back-link {
  color: #6b7280;
}

.spell-quest-wrapper .back-link:hover {
  color: #4b5563;
}

.spell-quest-wrapper .loading {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 400px;
  font-size: 1.25rem;
  color: white;
}

/* Responsive */
@media (max-width: 640px) {
  .spell-quest-wrapper .game-header {
    flex-direction: column;
    text-align: center;
  }

  .spell-quest-wrapper .game-main {
    padding: 1.5rem 1rem;
  }

  .spell-quest-wrapper .word-image {
    width: 120px;
    height: 120px;
  }

  .spell-quest-wrapper .answer-slot {
    width: 40px;
    height: 50px;
  }

  .spell-quest-wrapper .slot-letter {
    font-size: 1.25rem;
  }

  .spell-quest-wrapper .letter-tile {
    width: 45px;
    height: 55px;
    font-size: 1.5rem;
  }

  .spell-quest-wrapper .final-stats {
    flex-direction: column;
    gap: 1rem;
  }

  .spell-quest-wrapper .game-footer {
    flex-direction: column;
  }
}

/* Fullscreen Styles */
.spell-quest-wrapper.fullscreen-active {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9999;
  padding: 2rem;
  overflow-y: auto;
}

.spell-quest-wrapper.fullscreen-active .spell-quest-container {
  max-width: 1000px;
}

.spell-quest-wrapper.fullscreen-active .word-image {
  width: 200px;
  height: 200px;
}

.spell-quest-wrapper.fullscreen-active .answer-slot {
  width: 60px;
  height: 70px;
}

.spell-quest-wrapper.fullscreen-active .letter-tile {
  width: 65px;
  height: 75px;
  font-size: 2rem;
}

