.word-pop-container.fullscreen-mode {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100vw;
  height: 100vh;
  z-index: 9999;
  min-height: 100vh;
}

@keyframes cloud-float {
  0%, 100% {
    transform: translateY(0) translateX(0);
  }
  50% {
    transform: translateY(-10px) translateX(10px);
  }
}

@keyframes cloud-float-delayed {
  0%, 100% {
    transform: translateY(0) translateX(0);
  }
  50% {
    transform: translateY(-15px) translateX(-5px);
  }
}

.cloud-float {
  animation: cloud-float 4s ease-in-out infinite;
}

.cloud-float-delayed {
  animation: cloud-float-delayed 5s ease-in-out infinite;
  animation-delay: 1s;
}

@keyframes balloon-wiggle {
  0%, 100% {
    transform: rotate(-2deg) translateX(0);
  }
  25% {
    transform: rotate(2deg) translateX(4px);
  }
  50% {
    transform: rotate(-1deg) translateX(-3px);
  }
  75% {
    transform: rotate(3deg) translateX(2px);
  }
}

.balloon-wiggle {
  animation: balloon-wiggle 2.5s ease-in-out infinite;
}

@keyframes balloon-float-0 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-15px); }
}

@keyframes balloon-float-1 {
  0%, 100% { transform: translateY(-5px); }
  50% { transform: translateY(-20px); }
}

@keyframes balloon-float-2 {
  0%, 100% { transform: translateY(-10px); }
  50% { transform: translateY(5px); }
}

@keyframes balloon-float-3 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

.balloon-pop {
  opacity: 0 !important;
  transform: scale(1.5) !important;
  pointer-events: none;
}

@media (max-width: 640px) {
  .word-pop-container {
    min-height: calc(100vh - 80px);
  }
}

